const { contextBridge, ipcRenderer } = require('electron');
contextBridge.exposeInMainWorld('api', {
  getState: () => ipcRenderer.invoke('state'),
  onState: (cb) => ipcRenderer.on('state', (_, s) => cb(s)),
  action: (a) => ipcRenderer.invoke('action', a),
  login: () => ipcRenderer.invoke('login'),
  logout: () => ipcRenderer.invoke('logout'),
  startDrag: () => ipcRenderer.send('drag'),
  addAsset: (name, data) => ipcRenderer.invoke('asset:add', name, data),
  saveDesign: (d, select) => ipcRenderer.invoke('design:save', d, select),
  deleteDesign: (id) => ipcRenderer.invoke('design:delete', id),
  exportDesign: (id) => ipcRenderer.invoke('design:export', id),
  importDesign: () => ipcRenderer.invoke('design:import'),
  copy: (t) => ipcRenderer.invoke('copy', t),
  urls: () => ipcRenderer.invoke('urls'),
  setMini: (on) => ipcRenderer.invoke('mini:set', on),
  setPinned: (on) => ipcRenderer.invoke('pin:set', on),
  uiFlags: () => ipcRenderer.invoke('ui:flags'),
  onMini: (cb) => ipcRenderer.on('mini', (_, v) => cb(v)),
  onPinned: (cb) => ipcRenderer.on('pinned', (_, v) => cb(v)),
  updateState: () => ipcRenderer.invoke('update:state'),
  onUpdate: (cb) => ipcRenderer.on('update', (_, v) => cb(v)),
  checkUpdate: () => ipcRenderer.invoke('update:check'),
  installUpdate: () => ipcRenderer.invoke('update:install'),
  openReleases: () => ipcRenderer.invoke('update:releases'),
});
